// DB/runtime types are generated by Wrangler from the local deployment configuration.
export type Environment = Omit<
  Cloudflare.Env,
  "AUTH_ORIGIN" | "AUTH_SECRET" | "ACCOUNTS_ENABLED"
> & {
  AUTH_ORIGIN: string;
  AUTH_SECRET: string;
  ACCOUNTS_ENABLED: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  MAIL_RELAY_URL?: string;
  MAIL_RELAY_SECRET?: string;
  SITES_NATIVE_AUTH?: string;
};
